python3 << 'EOF'
# Let me check all pages to see if maybe there's yield data beyond what we've found
import json

with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Check all pages for any data in the yield table format
pages_with_yields = {}
for i, elem in enumerate(data['document']['elements']):
    content = elem.get('content', '') or ''
    if 'New Aa corporate' in content or 'Aa corporate bonds' in content:
        if 'bbox' in elem and elem['bbox']:
            for b in elem['bbox']:
                if b.get('page_id'):
                    if b['page_id'] not in pages_with_yields:
                        pages_with_yields[b['page_id']] = []
                    pages_with_yields[b['page_id']].append(i)

print("Pages with AA corporate bond yield data:", sorted(pages_with_yields.keys()))

# Now for each page, let's see what data is there
for page in sorted(pages_with_yields.keys()):
    print(f"\nPage {page}:")
    for elem_idx in pages_with_yields[page]:
        content = data['document']['elements'][elem_idx].get('content', '') or ''
        # Extract all years mentioned
        import re
        years = set(re.findall(r'>(\d{4})<', content))
        print(f"  Element {elem_idx}: Years = {sorted(years)}")
        if '2003' in years:
            print(f"    *** HAS 2003 DATA! ***")
            print(f"    Preview: {content[:500]}")
